def run(query: str) -> str:
    q = query.lower()
    plans = {
        'crm': 'CRM Pro: $99/mo - Lead tracking, automated email campaigns, and pipeline analytics.',
        'analytics': 'Analytics Suite: $149/mo - Custom dashboards, funnel visualizer, and real-time alerts.',
        'enterprise': 'Enterprise Suite: $299/mo - Dedicated account manager, SSO, and 24/7 SLA.'
    }
    for k, desc in plans.items():
        if k in q:
            return desc
    return 'Plans: CRM Pro ($99/mo), Analytics Suite ($149/mo), Enterprise Suite ($299/mo).'

def run(budget: float) -> str:
    if budget >= 250:
        return 'Eligible for 20% annual discount tier.'
    elif budget >= 150:
        return 'Eligible for 10% annual discount tier.'
    return 'Standard monthly pricing applies (5% welcome coupon available).'
